    "protection_how_rep_desc": "ਆਪਣੇ ਸਾਊਦੀ ਫੈਕਟਰੀਆਂ ਖਾਤੇ ਰਾਹੀਂ ਭੁਗਤਾਨ ਕਰੋ। ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ ਰਾਹੀਂ ਭੁਗਤਾਨ ਕਰਨ 'ਤੇ ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਇਹ ਸਾਊਦੀ ਫੈਕਟਰੀਆਂ ਦੇ ਸਰਕਾਰੀ ਬੈਂਕ ਖਾਤੇ ਵਿੱਚ ਭੇਜਿਆ ਗਿਆ ਹੈ।",
