    "protection_payments_desc2": "ਸਾਊਦੀ ਫੈਕਟਰੀਆਂ ਰਾਹੀਂ ਕੀਤਾ ਗਿਆ ਹਰ ਲੈਣ-ਦੇਣ SSL ਇਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਡਾਟਾ ਸੁਰੱਖਿਆ ਪ੍ਰੋਟੋਕੋਲਾਂ ਨਾਲ ਸੁਰੱਖਿਅਤ ਹੈ।",
    "protection_payments_link": "ਸੁਰੱਖਿਅਤ ਭੁਗਤਾਨ ਤਰੀਕਿਆਂ ਬਾਰੇ ਜਾਣੋ",
    "protection_delivery_desc1": "ਇਹ ਜਾਣ ਕੇ ਕਿ ਤੁਹਾਡਾ ਆਰਡਰ ਇੱਕ ਨਿਸ਼ਚਿਤ, ਗਾਰੰਟੀਸ਼ੁਦਾ ਮਿਤੀ 'ਤੇ ਭੇਜਿਆ ਜਾਂ ਡਿਲੀਵਰ ਕੀਤਾ ਜਾਵੇਗਾ, ਆਪਣੀ ਵਸਤੂ-ਸੂਚੀ ਦੀ ਬਿਹਤਰ ਯੋਜਨਾ ਅਤੇ ਪ੍ਰਬੰਧਨ ਕਰੋ।",
